<template><view class="app-page trip-page" :class="{'kx-care':prefs.care,'kx-dark':prefs.theme==='dark','kx-system':prefs.theme==='system','kx-reduce-motion':prefs.reduceMotion}" :style="mobilePreferenceStyle(prefs)"><view class="trip-header"><text class="back" @click="back">‹ {{$t('m2.mobile.back')}}</text><text class="kicker">{{$t('m2.trip.kicker')}}</text><text class="page-heading">{{$t('m2.mobile.homeTrips')}}</text><text class="subline">{{$t('m2.trip.noRouteBooking')}}</text></view>
 <view class="sort-bar"><picker :range="[$t('m2.trip.sort.rank'),$t('m2.trip.sort.latest'),$t('m2.trip.sort.score')]" :value="sort==='rank'?0:sort==='latest'?1:2" @change="changeSort"><view class="sort-select">{{sort==='rank'?$t('m2.trip.sort.rank'):sort==='latest'?$t('m2.trip.sort.latest'):$t('m2.trip.sort.score')}} ⌄</view></picker><text @click="load">{{$t('m2.trip.refresh')}}</text></view>
